router.get('/api/tickets/:ticketId/agent-activity-stream', requireSession, async (req, res) => {
  const ticket = await Ticket.findByPk(req.params.ticketId);
  if (!ticket || (ticket.customerId !== req.session.userId && !req.session.isAgent)) {
    return res.status(403).json({ error: 'Access to ticket activity stream denied' });
  }

  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');

  const onActivity = (activity) => {
    if (!req.session.isAgent && activity.isInternalNote) return;
    res.write(`data: ${JSON.stringify(activity)}\n\n`);
  };

  ticketBus.on(`ticket:${req.params.ticketId}:activity`, onActivity);
  req.on('close', () => {
    ticketBus.off(`ticket:${req.params.ticketId}:activity`, onActivity);
  });
});
